function minOperations(nums) {
  // Breadth-first search over every array state, kept as a bitmask with bit j = nums[j].
  const n = nums.length;
  const full = (1 << n) - 1;
  let start = 0;
  nums.forEach((v, j) => { if (v === 1) start |= 1 << j; });
  const dist = new Map([[start, 0]]);
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const state = queue[head];
    if (state === full) return dist.get(state);
    for (let i = 0; i < n; i++) {
      const next = state ^ (full ^ ((1 << i) - 1));
      if (!dist.has(next)) { dist.set(next, dist.get(state) + 1); queue.push(next); }
    }
  }
  return -1;
}

