function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000, style = pick(0, 3), first = pick(0, 1);
    const nums = [];
    while (nums.length < n) {
      if (style === 0) nums.push(rand() < 0.5 ? 0 : 1);
      else if (style === 1) { const bit = pick(0, 1); for (let run = pick(1, 40); run > 0 && nums.length < n; run--) nums.push(bit); }
      else if (style === 2) nums.push((first + nums.length) % 2);
      else nums.push(rand() < 0.97 ? 1 : 0);
    }
    return [nums];
  }
  const n = pick(1, 10);
  const ones = [0.2, 0.5, 0.8][pick(0, 2)];
  return [Array.from({ length: n }, () => (rand() < ones ? 1 : 0))];
}
